INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1229719-gs318', 'stk-user4760', 'GS 318', 'info', '{"desc": "عليكم السلام و الرحمه …\n\nو الله الدكتور هذا ممكن يعجب فئه معينه و ممكن لا …\n\nبالنسبه كان عندي غيابين …\n\nنظام الدكتور ما يحب المشاركه واجد يعني تشارك على الخفيف …\n\nو الدكتور مستاهل اذا بتغيب ارسل له رساله قبلها و اشرح له ظرفك و راح يتفهم …\n\nميجر ون جبت 19 من 20 و اعطى كل طالب بونص درجه …\n\nميجر تو جبت 16 من 20 و اعطى كل طالب بونص درجتين …\n\nالفايينل جبت 20 من 30 …\n\nالكلاس ورك عنده كوزين كل واحد من خمسه و جبت فيها 8 من عشره …\n\nو عنده كويز بس تيك هوم مخليه زي البحث و جبت فيه 5 من 5\n\nو برزنتشين امره سهلات جبت فيه 5 من 5\n\nالمشاركه و الغياب عليها 10 و اعطاني 10 …\n\nمجموعي تقريبا بين البي و البي بلس …\n\nنزلها في الترانسكربت a …\n\nيعني عطاني فوق حقي …\n\nبس اذا كنت مهتم معاه راح يعطيك اي بلس لو انك جايب العيد و فيه طلاب قالهم بالفاينل انتم اي بلس …\n\nبشكل عام الكلاس ممتع مع الدكتور نواف و اسلوبه مرح بس اهم شي ما تعدا وياه و لا تكون خلني اقولها بالعامي بثر لان فيه بعض الطلاب ما ينعطون وجه …\n\nاتمنى اني افتدك اخوي و نصيحه مني نزل معاه و لا تغيب و صدقني راج تاخذ قريد اكثر من حلو …\n\nالله يوفقك ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-318/145310/2", "user": "user4760", "ts": 1369834287000, "tid": 145310, "pn": 2}}', 1369834287000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381072-gs318', 'stk-7m00d', 'GS 318', 'info', '{"desc": "انا اخذت 423 عند مارك تومسون و المدرس جدا ابداع و اخلاق الى ابعد الحدود الكوزات جدا سهله و المياجر بعد\nيحدد الكتاب و ما يطلع منه\nالمعلومات المهمه يعيدها تقريبا كل كلاس و المدرس يشرح على اساس ان بعض الطلاب الانقلش عندهم مش كويسه يشرحلك كل معلومه و الكلمه اذا ما فهمت معناها بس ارفع يدك و راح يعلمك وش معناها\n\nالمدرس بصراحه ما اقدر اوفيه حقه اخذت معه كورس 423 و 447\nاخلاقه عاليه و الكلاس ودك انه ما يخلص\n\nانصح بهذا الكورس اذا كان عند مارك تومسون بسسسسسسس\nهذا اللي اقدر افيدك فيه لان 318 ما اخذتها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-318-or-gs-423/162522/4", "user": "7m00d", "ts": 1403203122000, "tid": 162522, "pn": 4}}', 1403203122000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
